-- V476: Seed 128 Class 11 English Core Mock Tests (104 Real-Format 80M Papers + 24 Chapter-Wise 25M Mocks)

DO $$
DECLARE
    v_class_id UUID;
BEGIN
    SELECT id INTO v_class_id FROM learn_exam_types WHERE slug IN ('class-11', 'cbse-class-11') LIMIT 1;
    IF v_class_id IS NULL THEN
        SELECT id INTO v_class_id FROM learn_exam_types WHERE name ILIKE '%Class 11%' LIMIT 1;
    END IF;

    IF v_class_id IS NOT NULL THEN
        DELETE FROM learn_test_questions WHERE mock_test_id IN (SELECT id FROM learn_mock_tests WHERE id::text LIKE '11050000-%');
        DELETE FROM learn_mock_tests WHERE id::text LIKE '11050000-%';

        ON CONFLICT (id) DO NOTHING;

1. He failed despite working hard. (Adverb clause of contrast with "Although")
2. The girl won gold. She lives next door. (Adjective clause with "who")
3. Tell me the truth. Where did you keep the key? (Noun clause)
4. Wait here. I return from the office. (Adverb clause of time with "until")', NULL, NULL, 'CASE', 'English Core', 'Integrated Grammar (Tenses, Clauses & Reordering)', 4, '1. Although he worked hard, he failed.
2. The girl who lives next door won gold.
3. Tell me where you kept the key.
4. Wait here until I return from the office.', '4 × 1M = 4M', 'Apply precise subordinating conjunctions (although, who, where, until) to synthesise complex academic sentences.', '1. Although he worked hard, he failed.
2. The girl who lives next door won gold.
3. Tell me where you kept the key.
4. Wait here until I return from the office.', 'HARD', true),
        ('11051111-0000-4000-8000-00000000006b', 'Gap Filling (4 blanks):
Artificial intelligence (i) _____ (transform) diagnostics rapidly over the last five years. Doctors who (ii) _____ (adopt) imaging tools early report faster screening, provided strict human oversight (iii) _____ (maintain) at every stage so errors (iv) _____ (can/could) be prevented.', NULL, NULL, 'CASE', 'English Core', 'Integrated Grammar (Tenses, Clauses & Reordering)', 4, '(i) has transformed / has been transforming; (ii) adopted / adopt; (iii) is maintained; (iv) can.', '4 × 1M = 4M', 'Complete the medical-tech passage selecting accurate present perfect, passive, and modal forms.', '(i) has transformed / has been transforming; (ii) adopted / adopt; (iii) is maintained; (iv) can.', 'HARD', true),
        ('11051111-0000-4000-8000-00000000006c', 'Integrated Editing & Transformation (5 × 1M):
1. Reorder: not / only / did / help / she / me / also / encouraged / but / my team
2. Error fix: "Scarcely I stepped out when it started pouring."
3. Conditional: "If I _____ (be) the Principal, I would extend library hours."
4. Determiner: "_____ of the two applicants was selected due to incomplete forms." (Neither/None)
5. Clause ID: Identify clause type of "You may sit **wherever you like**."', NULL, NULL, 'LA', 'English Core', 'Integrated Grammar (Tenses, Clauses & Reordering)', 5, '1. Not only did she help me, but also encouraged my team.
2. Scarcely had I stepped out when it started pouring.
3. were.
4. Neither.
5. Adverb clause of place.', '1M × 5 = 5M', NULL, '1. Not only did she help me, but also encouraged my team.
2. Scarcely had I stepped out when it started pouring.
3. were.
4. Neither.
5. Adverb clause of place.', 'HARD', true),
        ('11051111-0000-4000-8000-00000000006d', 'What is the prescribed word limit and mark weightage for a CBSE Class 11 Classified Advertisement or Poster?', '{"A":"150 words, 5 marks","B":"Up to 50 words inside a neat box, 3 marks","C":"100 words, 4 marks","D":"20 words, 1 mark"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Writing (Classifieds & Posters)', 1, 'Short Writing tasks (Classifieds & Posters) carry 3 marks each with 50-word limit.', NULL, NULL, 'Short Writing tasks (Classifieds & Posters) carry 3 marks each with 50-word limit.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000006e', 'Which element is strictly avoided in Classified Advertisements (Situation Vacant / To-Let / For Sale)?', '{"A":"Contact phone/email","B":"Long full grammatical sentences and decorative sketches (write crisp keyword phrases in a box)","C":"Bold heading","D":"Price or rent"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Writing (Classifieds & Posters)', 1, 'Classifieds are charged per word/line so use terse keyword phrases.', NULL, NULL, 'Classifieds are charged per word/line so use terse keyword phrases.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000006f', 'Main visual requirement of a CBSE Poster (Awareness / Social Campaign) is:', '{"A":"Tiny 8-pt paragraphs","B":"Catchy slogan/title, balanced layout, simple sketch/visual cue, issuing authority at bottom inside a box","C":"Only address","D":"Full essay"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Writing (Classifieds & Posters)', 1, 'Eye-catching visual hierarchy within 50 words.', NULL, NULL, 'Eye-catching visual hierarchy within 50 words.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000070', 'Which heading fits an advertisement looking to hire a qualified Physics PGT teacher?', '{"A":"TO-LET","B":"SITUATION VACANT","C":"FOR SALE","D":"LOST AND FOUND"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Writing (Classifieds & Posters)', 1, 'Employers post under SITUATION VACANT; job seekers post under SITUATION WANTED.', NULL, NULL, 'Employers post under SITUATION VACANT; job seekers post under SITUATION WANTED.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000071', 'When selling a 2-year-old Honda City car, the classified column heading is:', '{"A":"MATRIMONIAL","B":"FOR SALE / VEHICLES FOR SALE","C":"SITUATION WANTED","D":"ACCOMMODATION WANTED"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Writing (Classifieds & Posters)', 1, 'Model, year, mileage, condition, expected price & contact under FOR SALE.', NULL, NULL, 'Model, year, mileage, condition, expected price & contact under FOR SALE.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000072', 'In a Poster issuing awareness against Cyberbullying or Drug Abuse, who is normally named at the bottom?', '{"A":"\"Issued in public interest by [Organisation / School Eco-Club]\"","B":"\"Yours lovingly\"","C":"\"Dear Editor\"","D":"\"Attachment enclosed\""}'::jsonb, 'A', 'MCQ', 'English Core', 'Short Writing (Classifieds & Posters)', 1, 'Clear issuing authority gives credibility.', NULL, NULL, 'Clear issuing authority gives credibility.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000073', 'List the 5 essential details to mention inside a "TO-LET" Classified Advertisement for a 2BHK flat.', NULL, NULL, 'VSA', 'English Core', 'Short Writing (Classifieds & Posters)', 2, 'Type & size (2BHK airy ground-floor flat), prime location & amenities (24x7 water/parking), preferred tenant (small family/executives), expected monthly rent, and contact number.', 'All 5 details cleanly listed (2M)', NULL, 'Type & size (2BHK airy ground-floor flat), prime location & amenities (24x7 water/parking), preferred tenant (small family/executives), expected monthly rent, and contact number.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-000000000074', 'Write a catchy 2-line rhyming slogan + issuing authority line for a Poster on "Organ Donation".', NULL, NULL, 'VSA', 'English Core', 'Short Writing (Classifieds & Posters)', 2, '"Live Beyond Life — Gift Eyes, Heart & Hope! One Donor Can Save Eight Lives." | Issued in public interest by Red Cross Youth Wing, Delhi.', 'Slogan (1M) + Issuing body (1M)', NULL, '"Live Beyond Life — Gift Eyes, Heart & Hope! One Donor Can Save Eight Lives." | Issued in public interest by Red Cross Youth Wing, Delhi.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-000000000075', 'Draft a "SITUATION VACANT" classified advertisement (50 words) for Horizon Public School seeking a PGT Chemistry teacher with 3+ years experience.', NULL, NULL, 'SA', 'English Core', 'Short Writing (Classifieds & Posters)', 3, 'Boxed heading: SITUATION VACANT -> Wanted well-qualified M.Sc. (Chemistry), B.Ed. PGT with min. 3 yrs CBSE senior secondary teaching experience & fluent English. Attractive salary per norms. Send resume within 7 days to Principal, Horizon Public School, Pune / careers@horizon.edu.', 'Box & heading (1M) + Qualifications & contact (2M)', NULL, 'Boxed heading: SITUATION VACANT -> Wanted well-qualified M.Sc. (Chemistry), B.Ed. PGT with min. 3 yrs CBSE senior secondary teaching experience & fluent English. Attractive salary per norms. Send resume within 7 days to Principal, Horizon Public School, Pune / careers@horizon.edu.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-000000000076', 'Design a 50-word Poster (text + visual layout cue) for "Say No to Single-Use Plastics — Choose Green".', NULL, NULL, 'SA', 'English Core', 'Short Writing (Classifieds & Posters)', 3, 'Box -> Bold Title: SAY NO TO SINGLE-USE PLASTICS -> Slogan: "Plastic lasts 500 years; our planet can''t wait!" -> Visual cue: [Earth choked in plastic vs cloth bag] -> Bullet actions: Carry cloth bags, Steel bottles -> Issued by: Eco-Club, DPS Noida.', 'Layout & slogan (1.5M) + Content & issuing authority (1.5M)', NULL, 'Box -> Bold Title: SAY NO TO SINGLE-USE PLASTICS -> Slogan: "Plastic lasts 500 years; our planet can''t wait!" -> Visual cue: [Earth choked in plastic vs cloth bag] -> Bullet actions: Carry cloth bags, Steel bottles -> Issued by: Eco-Club, DPS Noida.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-000000000077', 'Draft a "LOST AND FOUND" classified (50 words) after losing a black leather briefcase containing Class 11 certificates & passport on Metro Yellow Line between Rajiv Chowk and Hauz Khas.', NULL, NULL, 'CASE', 'English Core', 'Short Writing (Classifieds & Posters)', 4, 'Boxed LOST & FOUND -> Lost black leather briefcase on Delhi Metro Yellow Line (Rajiv Chowk–Hauz Khas) on 26 Nov ~5 PM containing original Class 11 marksheet & passport. Finder will be suitably rewarded. Contact Arjun: 98XXXXXX10.', 'Format (1M) + Key identification details & reward (3M)', 'Context: Commuting home during evening rush hour, a student misplaced a vital folder on the metro and must publish an urgent 50-word newspaper notice.', 'Boxed LOST & FOUND -> Lost black leather briefcase on Delhi Metro Yellow Line (Rajiv Chowk–Hauz Khas) on 26 Nov ~5 PM containing original Class 11 marksheet & passport. Finder will be suitably rewarded. Contact Arjun: 98XXXXXX10.', 'HARD', true),
        ('11051111-0000-4000-8000-000000000078', 'Write BOTH short-writing formats cleanly: (a) A 50-word "FOR SALE" classified for selling household furniture before shifting abroad (2.5M), AND (b) A 50-word Poster promoting "Digital Safety & Strong Passwords" for teenagers (2.5M).', NULL, NULL, 'LA', 'English Core', 'Short Writing (Classifieds & Posters)', 5, 'Both tasks boxed cleanly with exact headings, crisp keyword phrases in (a) [teak dining set, refrigerator, sofa, good condition, price negotiable, contact], and catchy warning slogan + 3 bullet tips + Cyber Cell issuing line in (b).', '(a) 2.5M + (b) 2.5M', NULL, 'Both tasks boxed cleanly with exact headings, crisp keyword phrases in (a) [teak dining set, refrigerator, sofa, good condition, price negotiable, contact], and catchy warning slogan + 3 bullet tips + Cyber Cell issuing line in (b).', 'HARD', true),
        ('11051111-0000-4000-8000-000000000079', 'What is the prescribed word limit and marks for CBSE Class 11 Speech or Debate Writing?', '{"A":"50 words, 3 marks","B":"120–150 words, 5 marks","C":"300 words, 10 marks","D":"80 words, 4 marks"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Writing (Speech & Debate Writing)', 1, '120–150 words, 5 marks (Format 1, Content 2, Expression/Accuracy 2).', NULL, NULL, '120–150 words, 5 marks (Format 1, Content 2, Expression/Accuracy 2).', 'EASY', true),
        ('11051111-0000-4000-8000-00000000007a', 'In CBSE Debate Writing, a candidate MUST:', '{"A":"Support both \"for\" and \"against\" equally so nobody is offended","B":"Choose ONE clear side (\"FOR the motion\" OR \"AGAINST the motion\") and argue persuasively throughout","C":"Write it as a poem","D":"Skip formal salutation"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Writing (Speech & Debate Writing)', 1, 'Always state and stick strictly to one clear stance ("I strongly support / oppose the motion...").', NULL, NULL, 'Always state and stick strictly to one clear stance ("I strongly support / oppose the motion...").', 'EASY', true),
        ('11051111-0000-4000-8000-00000000007b', 'Standard opening salutation of a CBSE Debate is:', '{"A":"\"Dear Diary\"","B":"\"Honourable Chairperson, respected judges, and worthy opponents...\"","C":"\"To the Editor\"","D":"\"Hey friends\""}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Writing (Speech & Debate Writing)', 1, 'Formal address to judges, chair, and worthy opponents.', NULL, NULL, 'Formal address to judges, chair, and worthy opponents.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000007c', 'Which closing suits a formal School Assembly Speech best?', '{"A":"\"Thank you for your patient hearing.\"","B":"\"Yours faithfully\"","C":"\"Waiting for reply\"","D":"\"Signed, Applicant\""}'::jsonb, 'A', 'MCQ', 'English Core', 'Long Writing (Speech & Debate Writing)', 1, '"Thank you!" / "Thank you for lending me a patient ear."', NULL, NULL, '"Thank you!" / "Thank you for lending me a patient ear."', 'EASY', true),
        ('11051111-0000-4000-8000-00000000007d', 'Strong persuasive speeches rely effectively on:', '{"A":"Only slang","B":"Rhetorical questions, crisp statistics/examples, logical flow, and a memorable call-to-action","C":"Copy-pasting definitions","D":"Personal gossip"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Writing (Speech & Debate Writing)', 1, 'Rhetorical questions & clear evidence engage live audiences.', NULL, NULL, 'Rhetorical questions & clear evidence engage live audiences.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000007e', 'In a Debate rebuttal, "worthy opponents" are addressed respectfully to:', '{"A":"Insult them personally","B":"Counter their expected argument logically while maintaining parliamentary decorum","C":"Change your own stance mid-way","D":"End the speech early"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Writing (Speech & Debate Writing)', 1, 'Rebuttal shows live critical engagement.', NULL, NULL, 'Rebuttal shows live critical engagement.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000007f', 'Write an impactful 40-word opening hook (salutation + rhetorical question + thesis) for a Speech on "Mental Health Matters Among Teenagers".', NULL, NULL, 'VSA', 'English Core', 'Long Writing (Speech & Debate Writing)', 2, 'Respected Principal, teachers, and dear friends — when a classmate breaks an arm, we rush to sign their cast; why then do we stay silent when anxiety breaks their peace? Good morning! Today I stand to highlight why youth mental health needs equal care.', 'Salutation + Rhetorical hook + Thesis (2M)', NULL, 'Respected Principal, teachers, and dear friends — when a classmate breaks an arm, we rush to sign their cast; why then do we stay silent when anxiety breaks their peace? Good morning! Today I stand to highlight why youth mental health needs equal care.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-000000000080', 'Write two strong rebuttal arguments AGAINST the motion: "AI Tutors Will Completely Replace Human Classroom Teachers".', NULL, NULL, 'VSA', 'English Core', 'Long Writing (Speech & Debate Writing)', 2, '(1) While AI personalises drills, it cannot replicate human empathy, moral mentorship, or notice a quiet student''s emotional distress. (2) Peer discussion, teamwork, and live laboratory sparks grow only inside a human teacher''s classroom.', '2 reasoned points × 1M', NULL, '(1) While AI personalises drills, it cannot replicate human empathy, moral mentorship, or notice a quiet student''s emotional distress. (2) Peer discussion, teamwork, and live laboratory sparks grow only inside a human teacher''s classroom.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-000000000081', 'Outline the 4-paragraph structure of a 150-word CBSE Speech with exact purpose of each paragraph.', NULL, NULL, 'SA', 'English Core', 'Long Writing (Speech & Debate Writing)', 3, '1. Salutation & Hook (topic introduction). 2. Cause/Current Reality (facts/examples). 3. Impacts & Multi-angle Analysis. 4. Practical Solutions, Actionable Takeaway & Thank you.', '4 structural steps cleanly stated (3M)', NULL, '1. Salutation & Hook (topic introduction). 2. Cause/Current Reality (facts/examples). 3. Impacts & Multi-angle Analysis. 4. Practical Solutions, Actionable Takeaway & Thank you.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-000000000082', 'Write a persuasive Speech (120–150 words) on "Water Scarcity in Indian Cities: Why Every Drop Counts" highlighting rooftop harvesting, greywater recycling, and student pledges.', NULL, NULL, 'CASE', 'English Core', 'Long Writing (Speech & Debate Writing)', 4, 'Formal assembly greeting -> eye-opening urban crisis hook -> 3 concrete conservation actions (mandatory rooftop harvesting, dual plumbing/greywater, fixing leaky taps) -> inspiring pledge & Thank you.', 'Format (1M) + Content (2M) + Fluency (1M)', 'Assembly Context: As Head Boy/Girl during World Water Week, address students on moving from awareness slogans to measurable campus & home water conservation.', 'Formal assembly greeting -> eye-opening urban crisis hook -> 3 concrete conservation actions (mandatory rooftop harvesting, dual plumbing/greywater, fixing leaky taps) -> inspiring pledge & Thank you.', 'HARD', true),
        ('11051111-0000-4000-8000-000000000083', 'Write a Debate either FOR or AGAINST the motion: "Homework Should Be Abolished in Senior Secondary Classes" (120–150 words).', NULL, NULL, 'LA', 'English Core', 'Long Writing (Speech & Debate Writing)', 5, 'State stance clearly ("FOR/AGAINST the motion...") -> Address Chair, judges, worthy opponents -> Present 3 sharp reasoned points (e.g., AGAINST: independent problem-solving mastery, spaced-repetition retention for Physics/Maths, self-paced practice beyond hurried 40-min periods; rebut "burden" via balanced quality vs rote quantity) -> Firm closing & Thank you.', 'Stance & Format (1M) + Arguments & Rebuttal (2M) + Persuasive Expression & Accuracy (2M)', NULL, 'State stance clearly ("FOR/AGAINST the motion...") -> Address Chair, judges, worthy opponents -> Present 3 sharp reasoned points (e.g., AGAINST: independent problem-solving mastery, spaced-repetition retention for Physics/Maths, self-paced practice beyond hurried 40-min periods; rebut "burden" via balanced quality vs rote quantity) -> Firm closing & Thank you.', 'HARD', true),
        ('11051111-0000-4000-8000-000000000084', 'Write a Debate either FOR or AGAINST the motion: "Social Media Does More Harm Than Good to High School Students" (120–150 words).', NULL, NULL, 'LA', 'English Core', 'Long Writing (Speech & Debate Writing)', 5, 'Declare stance clearly -> Salutation -> 3 logical arguments + counter to opposing view (e.g., FOR: algorithmic dopamine addiction cutting deep study focus, sleep disruption, cyberbullying & comparison anxiety; or AGAINST: democratised free JEE/NEET/board lectures, global coding communities, creative portfolios) -> Strong closing.', 'Stance & Format (1M) + Arguments & Rebuttal (2M) + Accuracy (2M)', NULL, 'Declare stance clearly -> Salutation -> 3 logical arguments + counter to opposing view (e.g., FOR: algorithmic dopamine addiction cutting deep study focus, sleep disruption, cyberbullying & comparison anxiety; or AGAINST: democratised free JEE/NEET/board lectures, global coding communities, creative portfolios) -> Strong closing.', 'HARD', true),
        ('11051111-0000-4000-8000-000000000085', 'What is the prescribed title + numbering hierarchy in CBSE Note-Making (Section A, 8 Marks = 5M Notes + 3M Summary)?', '{"A":"Random bullet blobs","B":"Title, Main Headings (1, 2, 3...), Sub-headings (1.1, 1.2...), Sub-sub-headings (1.1.1) + Key to Abbreviations (min. 4) + Summary (~50 words)","C":"Roman essays only","D":"Full paragraphs copied verbatim"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension & Note-Making', 1, 'Strict indented decimal numbering + abbreviation key box + 50-word summary.', NULL, NULL, 'Strict indented decimal numbering + abbreviation key box + 50-word summary.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000086', 'How many standard or self-coined abbreviations should ideally appear inside the "Key to Abbreviations" box?', '{"A":"Zero","B":"At least 4–5 (e.g., edu., info., tech., gov., &)","C":"Fifty","D":"One only"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension & Note-Making', 1, '4–5 clear abbreviations used consistently in the notes.', NULL, NULL, '4–5 clear abbreviations used consistently in the notes.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000087', 'In Note-Making, complete sentences with auxiliary verbs ("is, are, was, the") should be:', '{"A":"Kept in full","B":"Omitted — use crisp noun/verb phrases instead of full sentences","C":"Written in bold","D":"Translated"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension & Note-Making', 1, 'Notes capture keywords/phrases concisely.', NULL, NULL, 'Notes capture keywords/phrases concisely.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000088', 'How long should the Summary following the Notes be (carrying 3 marks)?', '{"A":"250 words","B":"About 50 words (strictly derived from the notes in 1 smooth paragraph)","C":"10 words","D":"Copied paragraph 1 verbatim"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension & Note-Making', 1, '~50 words capturing main points coherently.', NULL, NULL, '~50 words capturing main points coherently.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000089', 'When solving an unseen factual case-study passage with a statistical chart, what must you check first?', '{"A":"Font style","B":"Axis units, percentages vs absolute counts, and exact year range","C":"Author''s age","D":"Page margins"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension & Note-Making', 1, 'Prevents misreading % vs raw numbers.', NULL, NULL, 'Prevents misreading % vs raw numbers.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000008a', 'Which abbreviation rule ensures clarity in Note-Making?', '{"A":"Invent illegible codes like \"xyz\"","B":"Keep first few letters / standard contractions / symbols (e.g., devt., envt., %, +ve) and list every one in the Key box","C":"Abbreviate titles only","D":"Never use symbols"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension & Note-Making', 1, 'Only recognisable abbreviations listed in the Key box.', NULL, NULL, 'Only recognisable abbreviations listed in the Key box.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000008b', 'Convert these two verbose sentences into crisp Note-Making sub-points using at least 2 abbreviations:
"Renewable solar and wind energy technologies have drastically reduced carbon emissions in metropolitan public transport networks."', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension & Note-Making', 2, '• Rnwbl. solar & wind tech. -> sharp drop in metro pub. trnspt. CO₂ emissions. (Key: Rnwbl. = Renewable, tech. = technology, pub. trnspt. = public transport)', 'Phrase compression (1M) + Abbreviations (1M)', NULL, '• Rnwbl. solar & wind tech. -> sharp drop in metro pub. trnspt. CO₂ emissions. (Key: Rnwbl. = Renewable, tech. = technology, pub. trnspt. = public transport)', 'MEDIUM', true),
        ('11051111-0000-4000-8000-00000000008c', 'List the 4 rules for writing a scoring 3-mark Summary in CBSE Class 11 English Core.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension & Note-Making', 2, '1. Stick to ~50 words in one cohesive paragraph. 2. Cover only main headings from your notes (never add outside views). 3. Write in complete grammatical third-person sentences without abbreviations/bullets. 4. Give/echo the central Title.', '0.5M × 4 = 2M', NULL, '1. Stick to ~50 words in one cohesive paragraph. 2. Cover only main headings from your notes (never add outside views). 3. Write in complete grammatical third-person sentences without abbreviations/bullets. 4. Give/echo the central Title.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-00000000008d', 'Unseen Passage Short Questions (4 × 1M):
(i) Why do urban forests lower city summer temperatures by 2–4°C? (ii) State two economic benefits of tree-lined avenues mentioned. (iii) Why are native species like neem and jamun preferred over exotic ornamental lawns? (iv) Pick one word from the text meaning "vital/essential".', NULL, NULL, 'CASE', 'English Core', 'Reading Comprehension & Note-Making', 4, '(i) Tree canopies shade asphalt while evapotranspiration cools surrounding air. (ii) Lower air-conditioning electricity bills and higher stormwater absorption reducing flood-repair costs. (iii) Native trees need far less irrigation, resist local pests, and shelter native birds/pollinators. (iv) Crucial.', '4 × 1M = 4M', 'Urban Forestry: Dense native tree corridors across Indian cities are crucial climate infrastructure. Broad canopies shield concrete streets from direct solar radiation while leaf evapotranspiration lowers ambient temperatures by 2–4°C, trimming household cooling power demand. Unlike water-thirsty exotic lawns, native species like neem, peepal, and jamun thrive in dry months while recharging monsoon aquifers and sustaining pollinators.', '(i) Tree canopies shade asphalt while evapotranspiration cools surrounding air. (ii) Lower air-conditioning electricity bills and higher stormwater absorption reducing flood-repair costs. (iii) Native trees need far less irrigation, resist local pests, and shelter native birds/pollinators. (iv) Crucial.', 'HARD', true),
        ('11051111-0000-4000-8000-00000000008e', 'NOTE-MAKING & SUMMARY (8 Marks: 5M Notes + 3M Summary):
(a) On the basis of reading the passage above, make notes on it using headings and sub-headings, recognisable abbreviations (minimum 4), and a suitable Title (5M).
(b) Write a summary of the passage in about 50 words (3M).', NULL, NULL, 'CASE', 'English Core', 'Reading Comprehension & Note-Making', 8, 'Title: Deep-Sea Hydrothermal Ecosystems
1. Discovery & Extreme Environment
  1.1 Discovered 1977 near Galapagos Rift (2,500+ m deep)
  1.2 Pitch dark, freezing ~2°C water, crushing pressure
  1.3 Superheated mineral vents (>350°C)
2. Chemosynthesis: Life Without Sunlight
  2.1 Bacteria oxidise H₂S instead of photoynth.
  2.2 Primary producers for blind shrimp, giant tube worms
  2.3 Symbiosis: Riftia worms house microbes in trophosome
3. Scientific & Astrobiological Importance
  3.1 Clues to origin of early Earth life
  3.2 Model for extraterrestrial oceans (Europa, Enceladus)
Key: envt.=environment; min.=mineral; photoynth.=photosynthesis; org.=origin
Summary (~50 words): Discovered in 1977 along deep ocean rifts, hydrothermal vents host thriving ecosystems completely independent of sunlight. Symbiotic bacteria harness hydrogen sulphide via chemosynthesis to nourish giant tube worms and shrimp amidst crushing pressure. These extreme habitats offer scientists vital insights into early Earth life and potential extraterrestrial oceans.', 'Title (1M) + Numbering & Content (3M) + Key to Abbr (1M) + 50-word Summary (3M)', 'Until 1977, biologists assumed every complex ecosystem on Earth depended ultimately on sunlight and photosynthesis. That certainty shattered when deep-sea submersibles exploring the Galapagos Rift over 2,500 metres beneath the Pacific discovered thriving colonies clustering around hydrothermal vents. Here, amid pitch darkness, freezing ambient water, and crushing pressure, volcanic fissures spew mineral-rich fluids exceeding 350°C. Instead of plants, specialised chemosynthetic bacteria oxidise toxic hydrogen sulphide to manufacture organic nutrients. Giant blind tube worms (Riftia pachyptila) — lacking mouths or digestive tracts — shelter billions of these microbes inside specialised trophosome tissue, alongside vent crabs and pale shrimp. Beyond rewriting marine ecology, these sunlit-free food webs serve astrobiologists as living models for how life could emerge on icy subterranean oceans of Jupiter''s moon Europa and Saturn''s Enceladus.', 'Title: Deep-Sea Hydrothermal Ecosystems
1. Discovery & Extreme Environment
  1.1 Discovered 1977 near Galapagos Rift (2,500+ m deep)
  1.2 Pitch dark, freezing ~2°C water, crushing pressure
  1.3 Superheated mineral vents (>350°C)
2. Chemosynthesis: Life Without Sunlight
  2.1 Bacteria oxidise H₂S instead of photoynth.
  2.2 Primary producers for blind shrimp, giant tube worms
  2.3 Symbiosis: Riftia worms house microbes in trophosome
3. Scientific & Astrobiological Importance
  3.1 Clues to origin of early Earth life
  3.2 Model for extraterrestrial oceans (Europa, Enceladus)
Key: envt.=environment; min.=mineral; photoynth.=photosynthesis; org.=origin
Summary (~50 words): Discovered in 1977 along deep ocean rifts, hydrothermal vents host thriving ecosystems completely independent of sunlight. Symbiotic bacteria harness hydrogen sulphide via chemosynthesis to nourish giant tube worms and shrimp amidst crushing pressure. These extreme habitats offer scientists vital insights into early Earth life and potential extraterrestrial oceans.', 'HARD', true),
        ('11051111-0000-4000-8000-00000000008f', 'NOTE-MAKING & SUMMARY (8 Marks: 5M Notes + 3M Summary):
(a) Prepare structured Notes with indented numbering, a suitable Title, and Key to Abbreviations (min. 4) (5M).
(b) Write a Summary in ~50 words (3M).', NULL, NULL, 'CASE', 'English Core', 'Reading Comprehension & Note-Making', 8, 'Title: Circular Economy & Electronic Waste
1. Growing Global E-Waste Crisis
  1.1 Fastest-growing solid waste (~62M tonnes/yr)
  1.2 Short device lifespans & planned obsolescence
  1.3 Toxic hazards: lead, mercury, brominated plastics
2. Shift from Linear to Circular Model
  2.1 Linear "take-make-dispose" wastes scarce metals
  2.2 Circular: right-to-repair, modular upgradeable hardware
  2.3 Urban mining recovers Au, Cu, Li efficiently
3. Policy & Consumer Action
  3.1 Extended Producer Responsibility (EPR) take-back rules
  3.2 Certified e-waste recyclers & refurbished tech
Key: tech.=technology; yrs.=years; haz.=hazards; recov.=recovery
Summary (~50 words): Rapid gadget upgrades generate over 62 million tonnes of toxic electronic waste annually under wasteful linear manufacturing. Shifting to a circular economy promotes modular repairable designs, Extended Producer Responsibility, and urban mining to recover gold, copper, and lithium cleanly—curbing soil pollution while conserving critical rare-earth minerals.', 'Notes (5M) + Summary (3M)', 'Discarded smartphones, laptops, and batteries now constitute the world''s fastest-growing waste stream, exceeding 62 million tonnes annually. Traditional linear manufacturing follows a "take-make-dispose" path, encouraged by glued non-repairable designs and rapid software obsolescence. When dumped in informal landfills, e-waste leaches lead, mercury, and toxic flame retardants into groundwater while squandering scarce metals. Transitioning toward a Circular Economy offers a sustainable remedy: designing modular hardware under Right-to-Repair laws extends gadget lifespans, while formal "urban mining" recovers gold, copper, cobalt, and lithium using far less energy than virgin ore extraction. Under Extended Producer Responsibility (EPR) rules, manufacturers must fund certified take-back recycling networks, empowering consumers to repair, refurbish, and recycle responsibly.', 'Title: Circular Economy & Electronic Waste
1. Growing Global E-Waste Crisis
  1.1 Fastest-growing solid waste (~62M tonnes/yr)
  1.2 Short device lifespans & planned obsolescence
  1.3 Toxic hazards: lead, mercury, brominated plastics
2. Shift from Linear to Circular Model
  2.1 Linear "take-make-dispose" wastes scarce metals
  2.2 Circular: right-to-repair, modular upgradeable hardware
  2.3 Urban mining recovers Au, Cu, Li efficiently
3. Policy & Consumer Action
  3.1 Extended Producer Responsibility (EPR) take-back rules
  3.2 Certified e-waste recyclers & refurbished tech
Key: tech.=technology; yrs.=years; haz.=hazards; recov.=recovery
Summary (~50 words): Rapid gadget upgrades generate over 62 million tonnes of toxic electronic waste annually under wasteful linear manufacturing. Shifting to a circular economy promotes modular repairable designs, Extended Producer Responsibility, and urban mining to recover gold, copper, and lithium cleanly—curbing soil pollution while conserving critical rare-earth minerals.', 'HARD', true),
        ('11051111-0000-4000-8000-000000000090', 'Read & Write Analytical Comprehension (5M):
(a) Explain how Citizen Science smartphone apps accelerate biodiversity tracking compared to small academic teams (2M).
(b) Mention two safeguards needed to ensure citizen-collected data stays scientifically reliable (2M).
(c) Give an antonym of "scarce" from the passage (1M).', NULL, NULL, 'LA', 'English Core', 'Reading Comprehension & Note-Making', 5, '(a) Millions of ordinary volunteers record timestamped, geotagged photos of birds, frogs, and flowering plants daily across backyards and trails — covering vast geographies unreachable by small research labs. (b) AI/expert community verification of uploaded photos and standardised observation protocols. (c) Abundant.', '(a) 2M + (b) 2M + (c) 1M', 'Once confined to university labs with scarce funding, wildlife monitoring has been transformed by Citizen Science. Equipped with smartphone apps, ordinary hikers, students, and retirees upload abundant geotagged photos of migrating butterflies, urban birds, and monsoon frogs daily. When paired with automated AI screening and expert botanist/ornithologist verification under standardised reporting templates, crowd-sourced datasets help ecologists detect shifting migration calendars and invasive pests decades earlier.', '(a) Millions of ordinary volunteers record timestamped, geotagged photos of birds, frogs, and flowering plants daily across backyards and trails — covering vast geographies unreachable by small research labs. (b) AI/expert community verification of uploaded photos and standardised observation protocols. (c) Abundant.', 'HARD', true),
        ('11051111-0000-4000-8000-000000000091', '[Passage 1: "Slow Architecture and Vernacular Climate Wisdom"]
Before mechanical air conditioning transformed urban skylines into sealed glass towers, builders across India relied on vernacular architecture calibrated to local climate. In arid Rajasthan, thick sandstone walls, shaded courtyards, and intricately carved stone lattice screens (jalis) channelled breezes while accelerating airflow through the Venturi cooling effect. In humid coastal Kerala, steeply pitched Mangalore-tiled roofs, deep verandahs, and open timber joinery allowed continuous cross-ventilation while deflecting monsoon downpours. Today, sustainable architects are reviving these passive cooling principles—combining breathable lime plasters and oriented courtyards with modern solar design to slash building operational energy use by nearly half.

Why did traditional builders in Rajasthan use carved stone jalis?', '{"A":"To block all sunlight completely","B":"To shade interiors while accelerating cooling breezes via the Venturi effect","C":"To store monsoon rainwater","D":"To support glass facades"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Jalis shaded spaces and accelerated breeze airflow through the Venturi cooling effect.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000092', '[From "Slow Architecture and Vernacular Climate Wisdom"] How did coastal Kerala homes adapt to heavy monsoon rain and humidity?', '{"A":"Sealed glass windows","B":"Steeply pitched tiled roofs, deep verandahs, and cross-ventilating timber joinery","C":"Thick subterranean basements","D":"Concrete flat slabs"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Pitched tiled roofs deflected rain while open joinery and verandahs enabled cross-ventilation.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000093', '[From "Slow Architecture and Vernacular Climate Wisdom"] Approximately how much operational energy can passive cooling architecture save today?', '{"A":"10%","B":"20%","C":"Nearly half (50%)","D":"95%"}'::jsonb, 'C', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (C) is correct. Passive principles combined with solar design slash energy use by nearly half.', 'Option (C) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000094', '[From "Slow Architecture and Vernacular Climate Wisdom"] Which word in the passage means "suited or adjusted accurately to a specific purpose"?', '{"A":"Sealed","B":"Calibrated","C":"Pitched","D":"Breathable"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. "Calibrated to local climate" means carefully tuned to climate conditions.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000095', '[From "Slow Architecture and Vernacular Climate Wisdom"] What contrasts modern sealed glass towers with traditional homes?', '{"A":"Modern towers depend heavily on mechanical air conditioning","B":"Traditional homes had no courtyards","C":"Glass towers use lime plaster exclusively","D":"Vernacular homes lacked ventilation"}'::jsonb, 'A', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (A) is correct. Mechanical air conditioning allowed sealed glass towers rather than passive ventilation.', 'Option (A) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000096', '[From "Slow Architecture and Vernacular Climate Wisdom"] What is "vernacular architecture" in this context?', '{"A":"Foreign imported skyscrapers","B":"Traditional local building styles evolved from regional materials and climate","C":"Temporary tents","D":"Underground tunnels"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Vernacular architecture uses regional materials like sandstone or Mangalore tiles tuned to local weather.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-000000000097', '[From "Slow Architecture and Vernacular Climate Wisdom"] Explain how modern sustainable architects are blending traditional wisdom with contemporary design.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension', 2, 'Modern architects pair passive features like shaded courtyards and breathable lime plasters with solar design principles, reducing mechanical cooling loads and cutting building operational energy consumption by nearly half.', 'Accurate short synthesis (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Keep answers concise and evidence-based. | Common Pitfall: Overlong verbatim copying.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-000000000098', '[From "Slow Architecture and Vernacular Climate Wisdom"] Compare the primary climate challenge addressed in Rajasthan versus coastal Kerala.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension', 2, 'Rajasthan homes tackled extreme dry heat using thick thermal-mass sandstone and jali cooling breezes, whereas Kerala homes countered heavy rain and humidity through steep pitched roofs and continuous cross-ventilation.', 'Accurate short synthesis (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Keep answers concise and evidence-based. | Common Pitfall: Overlong verbatim copying.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-000000000099', '[Case Passage: "Youth Skill Shift & Digital Micro-Credentials Survey"]
A 2025 survey of 1,200 Indian higher-secondary graduates examined preparedness for emerging workplaces. While 78% of students held strong theoretical scores in core subjects, 62% reported difficulty applying concepts to open-ended case projects. Notably, 44% had completed at least one short online micro-credential in data analysis, CAD modelling, or technical communication. Among students combining school academics with hands-on club projects, internship readiness scores averaged 81%, compared with 52% for theory-only peers.

What gap did 62% of surveyed graduates report despite strong theory marks?', '{"A":"Lack of exam halls","B":"Difficulty applying concepts to open-ended case projects","C":"Too many holidays","D":"Lack of school uniforms"}'::jsonb, 'B', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (B) is correct. 62% struggled to apply theoretical concepts to open-ended projects.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Match exact percentages from text. | Common Pitfall: Swapping stats.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000009a', '[From Case Data] What percentage of students completed online micro-credentials?', '{"A":"78%","B":"62%","C":"44%","D":"81%"}'::jsonb, 'C', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (C) is correct. 44% completed at least one short online micro-credential.', 'Option (C) [1 Mark]', NULL, 'Examiner Tip: Match exact percentages from text. | Common Pitfall: Swapping stats.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000009b', '[From Case Data] What was the internship readiness score difference between project-active and theory-only peers?', '{"A":"15 points","B":"29 percentage points (81% vs 52%)","C":"44 points","D":"Equal"}'::jsonb, 'B', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (B) is correct. 81% minus 52% = 29 percentage points.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Match exact percentages from text. | Common Pitfall: Swapping stats.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000009c', '[From Case Data] What was the sample size of the 2025 survey?', '{"A":"440 graduates","B":"810 graduates","C":"1,200 graduates","D":"2,025 graduates"}'::jsonb, 'C', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (C) is correct. The survey sampled 1,200 higher-secondary graduates.', 'Option (C) [1 Mark]', NULL, 'Examiner Tip: Match exact percentages from text. | Common Pitfall: Swapping stats.', 'EASY', true),
        ('11051111-0000-4000-8000-00000000009d', '[From Case Data] Suggest two school-level reforms supported by the survey findings.', NULL, NULL, 'VSA', 'English Core', 'Case Reading', 2, 'Schools should integrate interdisciplinary open-ended case projects alongside theoretical instruction and recognise verified practical club work or micro-credentials.', 'Insightful interpretation [2 Marks]', NULL, 'Examiner Tip: Cite percentage difference in comparison. | Common Pitfall: Ignoring numerical evidence.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-00000000009e', '[From Case Data] Interpret what the 81% vs 52% readiness gap demonstrates about learning methods.', NULL, NULL, 'VSA', 'English Core', 'Case Reading', 2, 'Combining conceptual study with hands-on project application significantly strengthens workplace problem-solving skills compared to rote memorisation alone.', 'Insightful interpretation [2 Marks]', NULL, 'Examiner Tip: Cite percentage difference in comparison. | Common Pitfall: Ignoring numerical evidence.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-00000000009f', 'Read the passage and complete BOTH parts:
"Effective sleep hygiene is a cornerstone of adolescent memory consolidation and emotional balance. Neuroscientists note that during deep slow-wave sleep, the brain replays daytime lessons, transferring fragile short-term traces from the hippocampus to permanent cortical networks. Conversely, chronic sleep debt below seven hours impairs attention span, slows reaction times, and heightens cortisol stress hormones. Practical habits include maintaining fixed wake-up times even on weekends, dimming bright blue-light screens an hour before bed, keeping bedrooms cool and dark, and avoiding late-evening caffeine."

(a) On the basis of your reading, make structured notes using recognisable abbreviations (minimum 4), proper indentation, and a suitable title. (5 Marks)
(b) Write a concise summary of the passage in about 50 words. (3 Marks)', NULL, NULL, 'CASE', 'English Core', 'Reading', 8, '(a) Title: Importance of Adolescent Sleep Hygiene
1. Role of Sleep in Brain
  1.1 Memory consolidation during slow-wave sleep
  1.2 Transfers traces: hippocampus → cortical networks
  1.3 Maintains emotional balance
2. Ill-Effects of Sleep Debt (<7 hrs)
  2.1 Impairs attn. span
  2.2 Slows react. time
  2.3 Raises cortisol (stress horm.)
3. Practical Habits
  3.1 Fixed wake-up time (incl. wknds.)
  3.2 Dim blue screens 1 hr pre-bed; cool/dark room; no late caffeine
Key to Abbreviations: attn. = attention; react. = reaction; horm. = hormone; incl. = including; wknds. = weekends.

(b) Summary: Adequate slow-wave sleep consolidates adolescent memories from the hippocampus to permanent cortical networks and supports emotional stability. Sleeping under seven hours impairs focus, reflexes, and elevates stress hormones. Establishing fixed wake times, reducing pre-bedtime screen exposure, maintaining cool dark bedrooms, and avoiding late caffeine ensure restorative sleep.', '(a) Title (1M) + Indented Numbered Notes (3M) + Key to Abbreviations (1M) [5 Marks] | (b) Cohesive 50-word Summary covering all main points [3 Marks]', NULL, 'Examiner Tip: Never write full sentences in Note-Making; always include a Key box with 4+ abbreviations! | Common Pitfall: Forgetting the Key to Abbreviations box or exceeding 50-word summary limit.', 'HARD', true),
        ('11051111-0000-4000-8000-0000000000a0', 'Fill in the blank with the correct tense: "By the time the chief guest arrived, the students ________ the exhibition models."', '{"A":"arrange","B":"had arranged","C":"are arranging","D":"will arrange"}'::jsonb, 'B', 'MCQ', 'English Core', 'Grammar (Tenses, Clauses, Voice & Transformation)', 1, 'Option (B) is correct. Earlier of two past actions uses Past Perfect ("had arranged").', 'Correct choice (B) [1 Mark]', NULL, 'Examiner Tip: Check tense and subject-verb number carefully. | Common Pitfall: Mixing clause word order.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000a1', 'Rearrange the jumbled words into a meaningful sentence:
"essential / critical thinking / is / for / scientific inquiry / rational"', '{"A":"Rational critical thinking is essential for scientific inquiry.","B":"Scientific inquiry for rational is essential critical thinking.","C":"Essential is rational thinking critical for scientific inquiry.","D":"Critical inquiry is scientific rational thinking essential."}'::jsonb, 'A', 'MCQ', 'English Core', 'Grammar (Tenses, Clauses, Voice & Transformation)', 1, 'Option (A) is correct. Standard Subject-Verb-Complement order: Rational critical thinking is essential for scientific inquiry.', 'Correct choice (A) [1 Mark]', NULL, 'Examiner Tip: Check tense and subject-verb number carefully. | Common Pitfall: Mixing clause word order.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000a2', 'Choose the correct clause completion: "Wait at the library desk ________."', '{"A":"until I return with the register","B":"because I returned yesterday","C":"although the bell rang","D":"unless it rained last week"}'::jsonb, 'A', 'MCQ', 'English Core', 'Grammar (Tenses, Clauses, Voice & Transformation)', 1, 'Option (A) is correct. Adverb clause of time matching imperative mood ("until I return...").', 'Correct choice (A) [1 Mark]', NULL, 'Examiner Tip: Check tense and subject-verb number carefully. | Common Pitfall: Mixing clause word order.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000a3', 'Identify the error in: "Neither of the two proposals were accepted by the committee."', '{"A":"Neither -> None","B":"were -> was","C":"accepted -> accepting","D":"by -> with"}'::jsonb, 'B', 'MCQ', 'English Core', 'Grammar (Tenses, Clauses, Voice & Transformation)', 1, 'Option (B) is correct. "Neither of + plural noun" takes a singular verb -> "was".', 'Correct choice (B) [1 Mark]', NULL, 'Examiner Tip: Check tense and subject-verb number carefully. | Common Pitfall: Mixing clause word order.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000a4', 'Transform to passive voice: "The meteorology department has issued a coastal cyclone alert."', '{"A":"A coastal cyclone alert was issued by the department.","B":"A coastal cyclone alert has been issued by the meteorology department.","C":"A coastal cyclone alert is issuing by the department.","D":"The meteorology department had issued a cyclone alert."}'::jsonb, 'B', 'MCQ', 'English Core', 'Grammar (Tenses, Clauses, Voice & Transformation)', 1, 'Option (B) is correct. Present perfect active ("has issued") converts to "has been issued".', 'Correct choice (B) [1 Mark]', NULL, 'Examiner Tip: Check tense and subject-verb number carefully. | Common Pitfall: Mixing clause word order.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000a5', 'Fill with the appropriate determiner: "________ knowledge of first aid can save a life during emergencies."', '{"A":"Few","B":"Many","C":"A little","D":"Every"}'::jsonb, 'C', 'MCQ', 'English Core', 'Grammar (Tenses, Clauses, Voice & Transformation)', 1, 'Option (C) is correct. "Knowledge" is uncountable; "A little" denotes small but positive useful quantity.', 'Correct choice (C) [1 Mark]', NULL, 'Examiner Tip: Check tense and subject-verb number carefully. | Common Pitfall: Mixing clause word order.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000a6', 'Reported speech transformation: She asked me, "Where did you keep the physics lab manual?"', '{"A":"She asked me where I had kept the physics lab manual.","B":"She asked me where had I kept the physics lab manual.","C":"She asked me if I kept the physics lab manual.","D":"She told me where I keep the manual."}'::jsonb, 'A', 'MCQ', 'English Core', 'Grammar (Tenses, Clauses, Voice & Transformation)', 1, 'Option (A) is correct. Wh-word acts as connector + subject before verb + Past Simple shifts to Past Perfect ("had kept").', 'Correct choice (A) [1 Mark]', NULL, 'Examiner Tip: Check tense and subject-verb number carefully. | Common Pitfall: Mixing clause word order.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000a7', 'You wish to sell your 2-year-old Hero Electric Optima scooter in excellent condition as you are shifting cities. Draft a classified advertisement in about 50 words for the "FOR SALE" column of a local newspaper.', NULL, NULL, 'SA', 'English Core', 'Creative Writing', 3, '┌─────────────────────────────────────────┐
                FOR SALE
Available 2024 Hero Electric Optima CX scooter, Matte Grey, single-hand driven (6,200 km only), dual removable Li-ion battery, 110 km range per charge, zero accidents, valid insurance up to Dec 2027. Expected price: ₹52,000 (negotiable). Owner relocating. Contact: Rohan, 98XXXXXXXX (between 5 p.m.–8 p.m.).
└─────────────────────────────────────────┘', 'Box + Heading FOR SALE [1 Mark] | Complete specs, price & contact within 50 words [2 Marks]', NULL, 'Examiner Tip: Classified ads avoid full grammatical sentences — use crisp comma-separated phrases inside a box! | Common Pitfall: Writing full letter-style paragraphs or omitting contact details.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-0000000000a8', 'Design an awareness poster in 50 words on behalf of your School Eco-Club promoting "Say No to Single-Use Plastics — Choose Sustainable Alternatives".', NULL, NULL, 'SA', 'English Core', 'Creative Writing', 3, '┌──────────────────────────────────────────┐
     🌍 DITCH PLASTIC, DEFEND OUR PLANET! 🌍

  ❌ Single-use bags choke oceans & soil for 500+ years
  ✅ Carry Cloth Totes • Steel Bottles • Bamboo Straws

  "Refuse Today So Tomorrow Can Breathe!"

  Issued in Public Interest by:
  Green Earth Eco-Club, Kendriya Vidyalaya
└──────────────────────────────────────────┘', 'Box + Eye-catching title & slogan [1 Mark] | Clear message + Issuing authority [2 Marks]', NULL, 'Examiner Tip: Always end a poster with "Issued by: <Organisation Name>" inside the border. | Common Pitfall: Forgetting issuing authority or slogan.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-0000000000a9', 'You are Ananya/Arjun, Head Girl/Head Boy of your school. Write a morning assembly speech in 120–150 words on "Mental Resilience and Handling Academic Stress Constructively".', NULL, NULL, 'LA', 'English Core', 'Creative Writing', 5, 'Good morning respected Principal, teachers, and dear friends.

Today, I wish to speak on a subject close to every senior secondary student: building mental resilience amidst academic pressure. Examinations evaluate what we have learnt—never our worth as human beings. When stress mounts, endless comparison with peers only clouds focus.

True resilience begins with breaking vast syllabi into manageable daily milestones, prioritising seven hours of sleep, and staying physically active. Equally vital is speaking openly with parents, teachers, or friends whenever anxiety feels heavy—seeking support is a sign of strength, not weakness. Let us pursue curiosity over panic, measure progress against our own yesterday, and support one another with kindness.

Thank you, and have a balanced day ahead!', 'Salutation + opening hook & formal closing [1 Mark] | Actionable stress-management ideas [2.5 Marks] | Oratorical tone, coherence & accuracy [1.5 Marks]', NULL, 'Examiner Tip: Begin with formal greeting ("Good morning Principal, teachers...") and end with "Thank you". | Common Pitfall: Writing an essay without addressing a live audience.', 'HARD', true),
        ('11051111-0000-4000-8000-0000000000aa', 'Write a debate in 120–150 words either FOR or AGAINST the motion: "Artificial Intelligence Tutors Will Replace Classroom Teachers Within Two Decades."', NULL, NULL, 'LA', 'English Core', 'Creative Writing', 5, '[AGAINST THE MOTION]
Honourable Chairperson, respected judges, and worthy opponents,

I stand firmly AGAINST the motion that AI tutors will replace classroom teachers. While AI excels at instant quiz grading and adaptive drills, genuine education extends far beyond information delivery.

A human teacher reads unspoken anxiety on a student''s face, sparks ethical curiosity during class debates, adapts humour to re-engage a tired room, and models empathy and resilience—qualities no algorithm can truly feel or replicate. Furthermore, school classrooms build social collaboration, teamwork, and peer friendship essential for holistic development. AI is undeniably a powerful teaching assistant that frees educators from routine clerical work, but it can never replace the mentorship, moral compass, and human warmth of a teacher.

Therefore, the future belongs to teachers empowered by AI—not teachers replaced by it. Thank you!', 'Clear stand (FOR or AGAINST) + formal debate address [1 Mark] | Logical arguments + rebuttal of opposing view [2.5 Marks] | Persuasive expression & accuracy [1.5 Marks]', NULL, 'Examiner Tip: Pick ONE clear side (never sit on the fence in a debate!) and address the Chairperson/judges. | Common Pitfall: Arguing both for and against equally without taking a clear side.', 'HARD', true),
        ('11051111-0000-4000-8000-0000000000ab', 'Read the thematic context of "A Photograph":
Looking at an old cardboard photograph showing her mother at twelve smiling beside two cousins at the sea beach, the poet reflects on how the sea "appears to have changed less" while human lives pass away, leaving only poignant silence.

Answer (3 Marks):
(a) Contrast the permanence of the sea with the transience of human life. (2M)
(b) What does the poet mean by "Its silence silences" at the conclusion? (1M)', NULL, NULL, 'SA', 'English Core', 'Hornbill Poetry Extract', 3, '(a) The sea represents eternal nature that remains virtually unchanged over decades, whereas the mother aged, cherished the memory with bittersweet laughter, and eventually passed away.
(b) The overwhelming grief and stillness left by her mother''s death leaves the poet speechless with nothing left to say.', '(a) Sea permanence vs human mortality [2 Marks] | (b) Mute grief of loss [1 Mark]', NULL, 'Examiner Tip: Highlight "terribly transient feet" as transferred epithet for human mortality. | Common Pitfall: Confusing the mother''s childhood laugh with her later nostalgic laugh.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-0000000000ac', 'Read the context of "The Portrait of a Lady":
After returning from five years abroad, the narrator''s grandmother welcomed him quietly, gathered neighbourhood women to beat an old drum singing of warriors'' homecoming, fell ill the next morning, and stopped talking to pray peacefully until her passing—while thousands of sparrows sat silently around her body ignoring bread crumbs.

Answer (3 Marks):
(a) Why was the grandmother''s evening drum-singing unusual for her routine? (1M)
(b) What did the silent sparrows'' refusal of bread crumbs signify? (2M)', NULL, NULL, 'SA', 'English Core', 'Hornbill Prose Extract', 3, '(a) It was the only occasion she omitted her evening prayers, overstraining herself in celebratory joy at her grandson''s return.
(b) It demonstrated a deep spiritual bond of silent mourning and grief among the birds for the gentle soul who had fed them lovingly every afternoon.', '(a) Only time she skipped prayers [1 Mark] | (b) Silent mourning & selfless bond [2 Marks]', NULL, 'Examiner Tip: Note how quietly the sparrows flew away once the corpse was carried off. | Common Pitfall: Saying the sparrows were angry at the family.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-0000000000ad', 'Read the context of "The Address":
After World War II, the narrator visits Mrs. Dorling''s house (No. 46 Marconi Street) to reclaim her dead mother''s silver cutlery, table-cloth, and antique plates. Seated inside a stuffy room surrounded by her family''s familiar belongings arranged tastelessly, she suddenly decides to leave without taking anything.

Answer (4 Marks):
(a) Why did the familiar belongings lose their value for the narrator inside Mrs. Dorling''s room? (2M)
(b) Why did she resolve to forget the address at the end? (2M)', NULL, NULL, 'SA', 'English Core', 'Snapshots Extract', 4, '(a) Placed in strange, tasteless surroundings and severed from the living mother who had used them, the objects only evoked painful memories of war loss rather than comfort.
(b) Of all things she had to forget, forgetting No. 46 Marconi Street was easiest and wisest so she could let go of a haunting past and move forward.', '(a) Estranged objects severed from lost life [2 Marks] | (b) Closure and moving forward from war trauma [2 Marks]', NULL, 'Examiner Tip: Contrast Mrs. Dorling''s hoarding greed with the narrator''s emotional liberation. | Common Pitfall: Thinking the narrator forgot the house number accidentally.', 'HARD', true),
        ('11051111-0000-4000-8000-0000000000ae', 'How did six-year-old Jonathan and his sister Suzanne display extraordinary courage aboard the damaged yacht "Wavewalker"? (40–50 words)', NULL, NULL, 'SA', 'English Core', 'Hornbill Short Answer', 3, 'Despite severe head swelling and deep arm cuts, seven-year-old Suzanne refused to trouble her busy father and drew a comforting caricature card thanking her parents. Six-year-old Jonathan told his father they weren''t afraid to die if they could all be together—rekindling the captain''s resolve to save them.', 'Suzanne''s endurance & card + Jonathan''s fearless words [3 Marks]', NULL, 'Examiner Tip: Always quote Jonathan''s exact inspiring sentiment. | Common Pitfall: Mixing up the ages or omitting Suzanne''s hidden injury.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-0000000000af', 'Why was King Tutankhamun''s mummy subjected to a CT scan in 2005, and what modern forensic mystery did it address?', NULL, NULL, 'SA', 'English Core', 'Hornbill Short Answer', 3, 'In 1922 Howard Carter had chiselled Tut''s resin-cemented body apart, and a 1968 X-ray revealed missing breastbone and front ribs, sparking murder theories. The 2005 CT scan created 1,700 digital cross-sectional X-ray slices to reconstruct Tut''s head and examine the true cause and age of his sudden teenage death.', 'Carter/1968 mystery + 2005 3D CT reconstruction [3 Marks]', NULL, 'Examiner Tip: Contrast 1922 treasure-focused archaeology with 2005 non-invasive medical forensic archaeology. | Common Pitfall: Saying the 2005 CT scan confirmed murder conclusively.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-0000000000b0', 'Why did Dr. Andrew Manson feel that his exhausting night in Blaenelly had produced "something real at last"? (40–50 words)', NULL, NULL, 'SA', 'English Core', 'Snapshots Short Answer', 3, 'After a long, disheartening evening over personal conflict, Dr. Andrew refused to give up on Joe Morgan''s lifeless-looking newborn. Combining rapid hot-and-cold water immersion shocks with rhythmic chest compression for half an hour, he revived the asphyxiated infant and saved both mother and child—fulfilling his medical calling.', 'Persistence + hot/cold plunge & artificial respiration reviving infant [3 Marks]', NULL, 'Examiner Tip: Mention the condition: asphyxia pallida (white, limp newborn). | Common Pitfall: Forgetting he also had to revive the collapsing mother first.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-0000000000b1', 'Compare the views on human curiosity, nature''s resilience, and spiritual connection presented in "The Adventure" (Rajendra Deshpande & Gaitonde) OR "The Voice of the Rain" and "The Laburnum Top". Highlight how nature sustains renewal and harmony. (120–150 words)', NULL, NULL, 'LA', 'English Core', 'Hornbill Long Answer', 6, 'Both Walt Whitman''s "The Voice of the Rain" and Ted Hughes''s "The Laburnum Top" celebrate nature as a continuous, self-sustaining cycle of energy, beauty, and mutual renewal.

In "The Voice of the Rain", Whitman personifies rain as the "Poem of Earth", rising invisibly from land and sea to condense in clouds and return to wash droughts, nourish unborn seeds, and beautify its own origin—just as heartfelt art enriches its creator and listener alike.

Similarly, in "The Laburnum Top", a silent, yellowing September tree seems lifeless until a goldfinch arrives like a spark, filling the canopy with chittering, wing-tremors, and energy to feed her young before flying away into the infinite, leaving the tree quiet again.

Together, both poems reveal that nature is neither static nor silent: hidden cycles of nourishment and interdependence continually renew life.', 'Voice of the Rain cycle & Poem of Earth analogy [2.5 Marks] | Laburnum Top transformation by Goldfinch [2.5 Marks] | Unified conclusion & polished expression [1 Mark]', NULL, 'Examiner Tip: Balance both poems symmetrically and explain the "Poem of Earth" parallel clearly. | Common Pitfall: Summarising without drawing the thematic link of mutual renewal.', 'HARD', true),
        ('11051111-0000-4000-8000-0000000000b2', 'Honesty and mutual respect within families require courage to confront selfishness or temptation. Discuss this with reference to BOTH "The Summer of the Beautiful White Horse" (Aram & Mourad) AND "Mother''s Day" (Mrs. Pearson). (120–150 words)', NULL, NULL, 'LA', 'English Core', 'Snapshots Long Answer', 6, 'William Saroyan''s "The Summer of the Beautiful White Horse" and J.B. Priestley''s play "Mother''s Day" approach conscience and respect from contrasting angles—one through youthful temptation, the other through domestic exploitation.

In Saroyan''s story, Aram and Mourad belong to the impoverished Garoghlanian tribe, famous for eleven centuries of unbending honesty. Mourad''s passion for riding leads him to "borrow" John Byro''s white horse secretly, yet once John Byro trusts their family name rather than suspecting theft, the boys'' conscience awakens and they return the horse healthier and better-tempered.

In "Mother''s Day", Mrs. Pearson is treated like an unpaid servant by her husband George, daughter Doris, and son Cyril until Mrs. Fitzgerald swaps personalities to assert firm boundaries. Though humorous, the confrontation forces the Pearson family to respect Mrs. Pearson''s dignity and time.

Together, both works show that true harmony rests on moral courage and mutual regard.', 'Aram & Mourad''s Garoghlanian honour awakening [2.5 Marks] | Mrs. Pearson & Mrs. Fitzgerald''s assertion of domestic respect [2.5 Marks] | Thematic conclusion & grammar [1 Mark]', NULL, 'Examiner Tip: Mention John Byro''s famous phrase: "I would swear it is my horse if I didn''t know your parents." | Common Pitfall: Treating "Mother''s Day" merely as magic without noting social satire on gender equality.', 'HARD', true),
        ('11051111-0000-4000-8000-0000000000b3', '[Passage 1: "Deep-Sea Hydrothermal Vents and Extremophiles"]
Thousands of metres beneath sunlit ocean waves, where crushing pressures exceed 250 atmospheres and sunlight never penetrates, mineral-rich plumes erupt from volcanic fissures on the ocean floor known as hydrothermal vents. Until 1977, biologists assumed every food web on Earth ultimately depended on solar photosynthesis. Yet expedition submersibles discovered thriving ecosystems of giant tube worms, blind shrimp, and clams clustered around scalding vent chimneys. Their foundation lies in chemosynthetic bacteria that oxidise toxic hydrogen sulphide gas to convert dissolved carbon dioxide into organic nutrients—proving life can flourish entirely on Earth''s geothermal chemistry.

What fundamental biological assumption was overturned in 1977 at hydrothermal vents?', '{"A":"Oceans contain salt water","B":"Every Earth food web depends ultimately on solar photosynthesis","C":"Submersibles can dive deep","D":"Shrimp live in shallow reefs"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Before 1977, biologists assumed all food webs required sunlight and photosynthesis.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000b4', '[From "Deep-Sea Hydrothermal Vents and Extremophiles"] Which energy source powers the primary producers at deep-sea hydrothermal vents?', '{"A":"Moonlight","B":"Oxidation of hydrogen sulphide via chemosynthesis","C":"Coral reefs","D":"Ice melting"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Chemosynthetic bacteria oxidise hydrogen sulphide to synthesise organic nutrients.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000b5', '[From "Deep-Sea Hydrothermal Vents and Extremophiles"] Pressures at deep-sea hydrothermal vents typically exceed:', '{"A":"5 atmospheres","B":"25 atmospheres","C":"250 atmospheres","D":"1 atmosphere"}'::jsonb, 'C', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (C) is correct. The passage states crushing pressures exceed 250 atmospheres.', 'Option (C) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000b6', '[From "Deep-Sea Hydrothermal Vents and Extremophiles"] Which word in the passage means "cracks or narrow openings in rock"?', '{"A":"Plumes","B":"Fissures","C":"Nutrients","D":"Submersibles"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. "Volcanic fissures" refers to narrow openings/cracks on the ocean floor.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000b7', '[From "Deep-Sea Hydrothermal Vents and Extremophiles"] Which organisms act as the foundation of vent food webs?', '{"A":"Giant tube worms","B":"Blind shrimp","C":"Chemosynthetic bacteria","D":"Seaweeds"}'::jsonb, 'C', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (C) is correct. Chemosynthetic bacteria convert CO₂ into organic nutrients using H₂S energy.', 'Option (C) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000b8', '[From "Deep-Sea Hydrothermal Vents and Extremophiles"] Why does photosynthesis NOT happen at hydrothermal vents?', '{"A":"Water is too salty","B":"Sunlight never penetrates thousands of metres down","C":"Carbon dioxide is absent","D":"Bacteria eat all plants"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Total darkness prevails thousands of metres below the sunlit zone.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify against passage lines. | Common Pitfall: Assuming outside facts.', 'EASY', true),
        ('11051111-0000-4000-8000-0000000000b9', '[From "Deep-Sea Hydrothermal Vents and Extremophiles"] Explain why the discovery of vent extremophiles expanded scientists'' search for life beyond Earth.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension', 2, 'By showing thriving ecosystems powered solely by geothermal chemistry (chemosynthesis) under extreme pressure and zero sunlight, hydrothermal vents proved life might exist in subsurface oceans of icy moons like Europa or Enceladus.', 'Accurate short synthesis (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Keep answers concise and evidence-based. | Common Pitfall: Overlong verbatim copying.', 'MEDIUM', true),
        ('11051111-0000-4000-8000-0000000000ba', '[From "Deep-Sea Hydrothermal Vents and Extremophiles"] Distinguish between photosynthesis and chemosynthesis as described in the text.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension', 2, 'Photosynthesis uses sunlight to convert CO₂ into food in upper ecosystems, whereas chemosynthesis relies on bacteria oxidising hydrogen sulphide gas from volcanic vents to produce organic nutrients in total darkness.', 'Accurate short synthesis (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Keep answers concise and evidence-based. | Common Pitfall: Overlong verbatim copying.', 'MEDIUM', true)
